"use client";

import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "motion/react";

export function RotatingWordsTailwind({ prefix = "Ship", words = ["faster", "smoother", "bolder", "today"] }) {
  const [i, setI] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setI((n) => (n + 1) % words.length), 2000);
    return () => clearInterval(id);
  }, [words.length]);
  return (
    <span className="inline-flex items-baseline gap-[0.28em] text-4xl font-semibold tracking-tight text-zinc-100">
      {prefix}
      <span className="inline-grid overflow-hidden pb-[0.08em] align-bottom">
        {words.map((w) => (
          <span key={w} className="invisible whitespace-nowrap [grid-area:1/1]">{w}</span>
        ))}
        <AnimatePresence mode="wait" initial={false}>
          <motion.span
            key={i}
            className="whitespace-nowrap text-sky-400 [grid-area:1/1]"
            initial={{ y: "100%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: "-100%", opacity: 0 }}
            transition={{ type: "spring", stiffness: 300, damping: 25 }}
          >
            {words[i]}
          </motion.span>
        </AnimatePresence>
      </span>
    </span>
  );
}
